import bpy
import math

COLLECTION_NAME = "R6 Replay Cameras"
CAMERA_NAME = "R6Cam_dyn4mic_P01"
RIG_NAME = "R6Rig_dyn4mic_P01"
BOUNDS_NAME = "R6Bounds_dyn4mic_P01"
TRACK_NAME = "dyn4mic_P01"
TRACK_LABEL = "P01"
PLAYER_GUESS = "dyn4mic"
ACTOR_ID = "0000000000000000"
POSITION_PROP_ID = "000000009fdb05f000000000"
ROTATION_PROP_ID = "00000000c9dd05f000000000"
ROTATION_MODE = "wrapped"
LEVEL_CAMERA = false
YAW_OFFSET_DEG = 0
PITCH_OFFSET_DEG = 0
ROLL_OFFSET_DEG = 0
FPS = 60
FRAME_STEP = 1
LOCATION_SCALE = 1

BOUNDS_MIN = (-8.660807609558105, -47.261940002441406, 0.6831589341163635)
BOUNDS_MAX = (-8.660807609558105, -47.261940002441406, 0.7743759155273438)

def ensure_collection(name):
    collection = bpy.data.collections.get(name)
    if collection is None:
        collection = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(collection)
    return collection

def remove_existing_object(name):
    obj = bpy.data.objects.get(name)
    if obj is not None:
        bpy.data.objects.remove(obj, do_unlink=True)

def keyframe_prop(obj, key, value, frame):
    obj[key] = value
    obj.keyframe_insert(data_path=f'["{key}"]', frame=frame)

def create_bounds_object(name, bounds_min, bounds_max, collection):
    if bounds_min is None or bounds_max is None:
        return None
    min_x, min_y, min_z = bounds_min
    max_x, max_y, max_z = bounds_max
    verts = [
        (min_x, min_y, min_z),
        (max_x, min_y, min_z),
        (max_x, max_y, min_z),
        (min_x, max_y, min_z),
        (min_x, min_y, max_z),
        (max_x, min_y, max_z),
        (max_x, max_y, max_z),
        (min_x, max_y, max_z),
    ]
    edges = [
        (0, 1), (1, 2), (2, 3), (3, 0),
        (4, 5), (5, 6), (6, 7), (7, 4),
        (0, 4), (1, 5), (2, 6), (3, 7),
    ]
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(verts, edges, [])
    mesh.update()
    obj = bpy.data.objects.new(name, mesh)
    obj.display_type = 'WIRE'
    obj.hide_render = True
    collection.objects.link(obj)
    return obj

collection = ensure_collection(COLLECTION_NAME)
remove_existing_object(CAMERA_NAME)
remove_existing_object(RIG_NAME)
remove_existing_object(BOUNDS_NAME)
rig = bpy.data.objects.new(RIG_NAME, None)
rig.empty_display_type = 'PLAIN_AXES'
rig.empty_display_size = 0.5
rig.rotation_mode = 'XYZ'
collection.objects.link(rig)
camera_data = bpy.data.cameras.new(CAMERA_NAME)
camera = bpy.data.objects.new(CAMERA_NAME, camera_data)
camera.rotation_mode = 'XYZ'
camera.data.clip_end = 10000
camera.parent = rig
camera.location = (0, 0, 0)
camera.rotation_euler = (math.radians(90), 0, 0)
collection.objects.link(camera)
bounds = create_bounds_object(BOUNDS_NAME, BOUNDS_MIN, BOUNDS_MAX, collection)
scene = bpy.context.scene
scene.camera = camera
scene.render.fps = FPS
camera['r6_rig_name'] = RIG_NAME
rig['r6_track_name'] = TRACK_NAME
rig['r6_track_label'] = TRACK_LABEL
rig['r6_player_guess'] = PLAYER_GUESS
